IF EXISTS (SELECT 1 FROM [DIGEMID_Catalogo_Productos] WHERE CONCAT([Nom_Prod],[Concent],[Forma_Farmaceutica],[Presentacion],[Titular]) COLLATE Latin1_General_BIN2 LIKE N'%[' + NCHAR(194) + NCHAR(195) + NCHAR(162) + NCHAR(165) + NCHAR(65533) + ']%') THROW 50002, 'DIGEMID seed contains corrupted characters', 1;
